import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Scanner;

public class CopierColler {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.println("Donner le nom du fichier source :");
        String nomS = sc.nextLine();

        System.out.println("Donner le nom du fichier destination :");
        String nomD = sc.nextLine();

        try (FileReader fs = new FileReader(nomS);
             FileWriter fd = new FileWriter(nomD)) {

            int car;
            while ((car = fs.read()) != -1) {
                fd.write(car);
            }

            System.out.println("Copie terminée.");

        } catch (IOException e) {
            System.out.println("Erreur lors de la copie : " + e.getMessage());
        }

        sc.close();
    }
}

